  // Default (nothing saved yet, i.e. first-ever launch) is Korean -- only
  // an explicit saved "en" switches it back.
  let currentLang = (function () {
    try {
      const saved = localStorage.getItem('orapulseLang');
      return saved === 'en' ? 'en' : 'ko';
    } catch (_) {
      return 'ko'; // localStorage can throw in some restricted browser contexts -- fall back quietly
    }
  })();

  // Mirrors currentLang above. The actual data-theme attribute was already
  // applied to <html> by the tiny inline <script> at the very top of this
  // file (before first paint) -- this just gives the rest of the page's JS
  // (the #themeSelect wiring below) the same value to initialize the select
  // control from, so the two stay in sync. Default (nothing saved yet) is
  // light -- only an explicit saved "dark" switches it back.
  let currentTheme = (function () {
    try {
      const saved = localStorage.getItem('orapulseTheme');
      return saved === 'dark' ? 'dark' : 'light';
    } catch (_) {
      return 'light';
    }
  })();

  function t(key, vars) {
    const dict = I18N[currentLang] || I18N.en;
    let s = (key in dict) ? dict[key] : (I18N.en[key] !== undefined ? I18N.en[key] : key);
    if (vars) {
      Object.keys(vars).forEach(k => { s = s.split('{' + k + '}').join(vars[k]); });
    }
    return s;
  }

  // Static, one-time text: elements marked with data-i18n get their
  // textContent replaced; data-i18n-html gets innerHTML replaced (for the
  // few strings that legitimately contain markup, like the <br> in the
  // Main tab's footer note). Re-run on every language switch.
  function applyStaticI18n() {
    document.querySelectorAll('[data-i18n]').forEach(el => {
      el.textContent = t(el.getAttribute('data-i18n'));
    });
    document.querySelectorAll('[data-i18n-html]').forEach(el => {
      el.innerHTML = t(el.getAttribute('data-i18n-html'));
    });
    document.querySelectorAll('[data-i18n-title]').forEach(el => {
      el.title = t(el.getAttribute('data-i18n-title'));
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
      el.setAttribute('placeholder', t(el.getAttribute('data-i18n-placeholder')));
    });
  }

  // Raw data caches for each card/section, kept around purely so a language
  // switch can re-render already-loaded content client-side (using the same
  // data currently on screen) instead of re-fetching from the server. Each
  // one is set at the point its owning loadXxx() function receives a
  // successful response, and read back only by rerenderAll() below.
  let lastDbStatusData = null;
  let lastJobFailuresData = null;
  let lastAccountSecurityData = null;
  let lastAlertLogData = null;
  let lastOpsUsageData = null;
  let lastRecoveryUsageData = null;
  let lastTuningData = null;
  let lastTableStatsData = null;
  let lastTableStatsOwner = null;
  // The SQL Runner result isn't refreshed on a timer or on tab switch (see
  // TABS.sql above) -- it only changes when the user runs a new query -- so
  // this cache exists purely so a language switch can re-render the same
  // result set's row-count/cap-note text without re-running the query.
  let lastSqlRunnerData = null;

  // Re-applies the current language to both the static data-i18n markup and
  // every dynamic card that has data cached above. Called once on initial
  // load (in case a non-English language was restored from localStorage)
  // and again every time the user switches languages via #langSelect.
